## CVXPY SOURCE: reductions/solvers/qp_solvers/gurobi_qpif.py
## Gurobi QP solver interface for QP/MIQP problems
##
## Uses QpSolver.apply() for sign-correct A_eq/b_eq/F_ineq/g_ineq data.
## The ONLY QP solver that is MIP_CAPABLE (supports MIQP).
##
## Key differences from Gurobi_Conic_Solver:
##   - No SOC handling (quadratic constraints)
##   - Uses QP path (simpler, no auxiliary variables)
##   - Dual sign: negate ALL constraint duals (matching CVXPY gurobi_qpif.py line 120)


# -- Gurobi_QP_Solver class ---------------------------------------------------
## CVXPY SOURCE: gurobi_qpif.py lines 26-251

Gurobi_QP_Solver <- new_class("Gurobi_QP_Solver", parent = QpSolver,
  package = "CVXR",
  constructor = function() {
    if (FALSE) new_object(S7_object())  ## S7 static-check guard
    .fast_new(Gurobi_QP_Solver, S7_object(),
      .cache = new.env(parent = emptyenv()),
      MIP_CAPABLE = TRUE,
      BOUNDED_VARIABLES = TRUE,
      PSD_TRIANGLE_KIND = NA_character_,
      PSD_SQRT2_SCALING = NA,
      SUPPORTED_CONSTRAINTS = list(Zero, NonNeg),
      REQUIRES_CONSTR = FALSE
    )
  }
)

method(solver_name, Gurobi_QP_Solver) <- function(x) GUROBI_SOLVER

# -- reduction_apply -----------------------------------------------------------
## CVXPY SOURCE: gurobi_qpif.py:59-73
##   data, inv_data = super(GUROBI, self).apply(problem)
##   data['init_value'] = utilities.stack_vals(problem.variables, grb.GRB.UNDEFINED)
## S7 has no `super`; the parent method is invoked explicitly and its result
## extended, not rebuilt. GRB.UNDEFINED is 1e101; the R gurobi package takes NA
## for an undefined start entry (measured, gurobi 13.0.3).

method(reduction_apply, Gurobi_QP_Solver) <- function(x, problem, ...) {
  result <- method(reduction_apply, QpSolver)(x, problem, ...)
  if (!is.null(problem[["variables"]])) {
    result[[1L]][["init_value"]] <- stack_vals(problem[["variables"]], NA_real_)
  }
  result
}

# -- solve_via_data ------------------------------------------------------------
## CVXPY SOURCE: gurobi_qpif.py lines 139-241
## Receives QP data from QpSolver.apply(): P, q, A_eq, b_eq, F_ineq, g_ineq

method(solve_via_data, Gurobi_QP_Solver) <- function(x, data, warm_start = FALSE, verbose = FALSE,
                                                        solver_opts = list(), ...) {
  .require_solver_package(GUROBI_SOLVER)

  dots <- list(...)
  solver_cache <- dots[["solver_cache"]]

  q_vec <- data[["q"]]
  nvars <- length(q_vec)

  ## Build constraint matrix: stack A_eq and F_ineq
  A_eq <- data[["A_eq"]]
  b_eq <- data[["b_eq"]]
  F_ineq <- data[["F_ineq"]]
  g_ineq <- data[["g_ineq"]]

  len_eq <- nrow(A_eq)
  len_ineq <- nrow(F_ineq)
  n_constrs <- len_eq + len_ineq

  if (n_constrs > 0L) {
    if (len_eq > 0L && len_ineq > 0L) {
      A_model <- rbind(A_eq, F_ineq)
      rhs_model <- c(b_eq, g_ineq)
      sense_model <- c(rep("=", len_eq), rep("<", len_ineq))
    } else if (len_eq > 0L) {
      A_model <- A_eq
      rhs_model <- b_eq
      sense_model <- rep("=", len_eq)
    } else {
      A_model <- F_ineq
      rhs_model <- g_ineq
      sense_model <- rep("<", len_ineq)
    }
  } else {
    A_model <- Matrix::sparseMatrix(i = integer(0), j = integer(0),
                                     x = numeric(0), dims = c(0L, nvars))
    rhs_model <- numeric(0)
    sense_model <- character(0)
  }

  ## Build Gurobi model
  model <- list()
  model$modelsense <- "min"
  model$obj <- q_vec
  model$A <- A_model
  model$rhs <- rhs_model
  model$sense <- sense_model

  ## Quadratic objective: P for 0.5 x'Px + q'x -> Q = P/2 for Gurobi's x'Qx + c'x.
  ## CVXPY SOURCE: gurobi_qpif.py lines 211-212 (setMObjective(0.5 * P, q, 0.0)).
  ## Gurobi uses the FULL Q: a triangle alone halves every cross term. P is a
  ## dgCMatrix, so P / 2 needs no further coercion by the gurobi package.
  if (!is.null(data[[SD_P]])) {
    model$Q <- data[[SD_P]] / 2
  }

  ## Variable bounds
  lb <- data[[LOWER_BOUNDS]] %||% rep(-Inf, nvars)
  ub <- data[[UPPER_BOUNDS]] %||% rep(Inf, nvars)

  ## Variable types for MIP
  vtype <- rep("C", nvars)

  bool_idx <- data[["bool_idx"]]
  if (length(bool_idx) > 0L) {
    for (idx in bool_idx) {
      vtype[idx] <- "B"
      lb[idx] <- max(lb[idx], 0)
      ub[idx] <- min(ub[idx], 1)
    }
  }

  int_idx <- data[["int_idx"]]
  if (length(int_idx) > 0L) {
    for (idx in int_idx) {
      vtype[idx] <- "I"
    }
  }

  model$lb <- lb
  model$ub <- ub
  model$vtype <- vtype

  ## Solver parameters
  params <- list(OutputFlag = if (verbose) 1L else 0L)

  ## `env` has no R counterpart (gurobi_qpif.py:164-172); see
  ## .gurobi_reject_env in gurobi_conif.R.
  .gurobi_reject_env(solver_opts)

  ## Apply user solver options, skipping the arguments consumed by this
  ## interface (gurobi_qpif.py:216-219, `if key not in self.INTERFACE_ARGS`).
  for (opt_name in setdiff(names(solver_opts), GUROBI_INTERFACE_ARGS)) {
    params[[opt_name]] <- solver_opts[[opt_name]]
  }

  ## Warm-start. CVXPY SOURCE: gurobi_qpif.py:185-197 -- a cached model with
  ## an incumbent (`old_status in SOLUTION_PRESENT or old_model.solCount > 0`)
  ## seeds every column from its solution; otherwise, with warm_start, the
  ## user's current variable values do (`x_grb[idx].start = data['init_value'][idx]`).
  ## See gurobi_conif.R for why `!is.null(cached$x)` is the upstream condition
  ## and what 1.9.2.9159 changed (claims audit C0859).
  cache_key <- GUROBI_SOLVER
  start_vals <- NULL
  if (warm_start && !is.null(solver_cache) && exists(cache_key, envir = solver_cache)) {
    cached <- get(cache_key, envir = solver_cache)
    if (!is.null(cached$x) && length(cached$x) == nvars) {
      start_vals <- cached$x
    }
  } else if (warm_start && !is.null(data[["init_value"]])) {
    start_vals <- data[["init_value"]][seq_len(nvars)]
  }
  if (!is.null(start_vals)) model$start <- start_vals

  ## CVXPY SOURCE: gurobi_qpif.py:221-222
  ##   if 'save_file' in solver_opts: model.write(solver_opts['save_file'])
  if (!is.null(solver_opts[["save_file"]])) {
    gurobi::gurobi_write(model, solver_opts[["save_file"]], params)
  }

  ## Call Gurobi
  result <- gurobi::gurobi(model, params)

  ## Reoptimize on INF_OR_UNBD
  if (identical(result$status, "INF_OR_UNBD") &&
      isTRUE(solver_opts[["reoptimize"]])) {
    params$DualReductions <- 0L
    result <- gurobi::gurobi(model, params)
  }

  ## Cache for future warm-starts
  ## CVXPY SOURCE: gurobi_qpif.py lines 238-239
  if (!is.null(solver_cache)) {
    assign(cache_key, result, envir = solver_cache)
  }

  ## Store metadata
  result$.len_eq <- len_eq
  result$.n_constrs <- n_constrs
  result$.is_mip <- length(bool_idx %||% integer(0)) > 0L ||
    length(int_idx %||% integer(0)) > 0L

  result
}

# -- reduction_invert ----------------------------------------------------------
## CVXPY SOURCE: gurobi_qpif.py lines 75-137
## Dual sign: negate ALL pi duals -- matching CVXPY gurobi_qpif.py line 120.

method(reduction_invert, Gurobi_QP_Solver) <- function(x, solution, inverse_data, ...) {
  attr_list <- list()

  ## Map Gurobi string status to CVXR status
  status <- .status_from_map(GUROBI_STATUS_MAP, solution$status)

  ## Post-adjustment.
  ## CVXPY SOURCE: gurobi_qpif.py:102-104 -- the QP path has EXACTLY ONE rule:
  ##     if status == s.USER_LIMIT and not model.SolCount:
  ##         status = s.INFEASIBLE_INACCURATE
  ##
  ## CVXR also carried `SOLVER_ERROR + a primal -> OPTIMAL_INACCURATE`, which
  ## upstream has only on the CONIC side (gurobi_conif.py:274-275, ported in
  ## gurobi_conif.R and correct there). Removed: relabelling a solver error as
  ## a near-optimal solution is a claim CVXR cannot support -- Gurobi reported
  ## NUMERIC or CUTOFF, and the presence of an iterate says nothing about its
  ## optimality. Upstream still HANDS BACK that iterate (see the extraction
  ## condition below); it just does not lie about the status.
  if (status == USER_LIMIT && is.null(solution$x)) {
    status <- INFEASIBLE_INACCURATE
  }

  ## Timing
  if (!is.null(solution$runtime))
    attr_list[[RK_SOLVE_TIME]] <- solution$runtime
  ## CVXPY SOURCE: gurobi_qpif.py:82-98 -- NUM_ITERS is the barrier plus
  ## simplex sum ("one of them will be 0 anyway"), set unconditionally: a
  ## problem presolve finished reports 0, not NA (claims audit C0861).
  bar_iter <- solution$baritercount %||% 0L
  simplex_iter <- solution$itercount %||% 0L
  attr_list[[RK_NUM_ITERS]] <- bar_iter + simplex_iter
  ## CVXPY SOURCE: gurobi_qpif.py:99 -- EXTRA_STATS = model. See the note in
  ## gurobi_conif.R: the R result list stands in for the model object.
  attr_list[[RK_EXTRA_STATS]] <- .drop_private_fields(solution)

  ## CVXPY SOURCE: gurobi_qpif.py:106 --
  ##     if (status in s.SOLUTION_PRESENT) or (model.solCount > 0):
  ## The second disjunct is what makes dropping the promotion above SAFE: a
  ## Gurobi run that produced an iterate still returns it, so no information is
  ## lost relative to the old behavior -- only the mislabelled status is.
  ## `!is.null(solution$x)` is CVXR's `solCount > 0`.
  if (status %in% SOLUTION_PRESENT || !is.null(solution$x)) {
    opt_val <- solution$objval + inverse_data[[SD_OFFSET]]

    ## Primal variables
    primal_vars <- list()
    primal_vars[[as.character(inverse_data[[SOLVER_VAR_ID]])]] <- solution$x

    ## Dual variables: negate ALL pi duals
    ## CVXPY: y = -np.array([constraints_grb[i].Pi for i in range(m)])
    is_mip <- isTRUE(solution$.is_mip)

    if (!is_mip && !is.null(solution$pi)) {
      y <- -solution$pi
      len_eq <- solution$.len_eq

      eq_dual <- if (len_eq > 0L) {
        get_dual_values(
          y[seq_len(len_eq)],
          extract_dual_value,
          inverse_data[[SOLVER_EQ_CONSTR]]
        )
      } else {
        list()
      }

      ineq_dual <- if (len_eq < length(y)) {
        get_dual_values(
          y[(len_eq + 1L):length(y)],
          extract_dual_value,
          inverse_data[[SOLVER_NEQ_CONSTR]]
        )
      } else {
        list()
      }

      dual_vars <- c(eq_dual, ineq_dual)
    } else {
      dual_vars <- list()
    }

    Solution(status, opt_val, primal_vars, dual_vars, attr_list)
  } else {
    failure_solution(status, attr_list)
  }
}

# -- print ---------------------------------------------------------------------

method(print, Gurobi_QP_Solver) <- function(x, ...) {
  cat("Gurobi_QP_Solver()\n")
  invisible(x)
}
